import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname, join, resolve } from "node:path";
import type { Blobs } from "./blobs";

export function disk(root: string): Blobs {
  const base = resolve(root);
  // Keys are generated by core (uuid-based), but refuse anything that would escape the folder anyway.
  const at = (key: string) => {
    const p = resolve(join(base, key));
    if (!p.startsWith(base + "/")) throw new Error("bad blob key");
    return p;
  };
  return {
    async put(key, body, mime) {
      const p = at(key);
      await mkdir(dirname(p), { recursive: true });
      await writeFile(p, new Uint8Array(body));
      await writeFile(p + ".mime", mime ?? "");
    },
    async get(key) {
      try {
        const buf = await readFile(at(key));
        const mime = (await readFile(at(key) + ".mime", "utf8").catch(() => "")) || null;
        return { body: buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength) as ArrayBuffer, mime, size: buf.byteLength };
      } catch {
        return null;
      }
    },
  };
}
